// ==========================================
// EDITA AQUI la lista de servicios a vigilar
// ==========================================
const servicios = [
  { nombre: 'Sitio web', url: 'https://ejemplo.com' },
  { nombre: 'API interna', url: 'https://api.ejemplo.com/health' },
  { nombre: 'Panel admin', url: 'http://192.168.1.50:8080' },
];

return servicios.map(s => ({ json: s }));

// Junta el resultado HTTP con el nombre y URL del servicio original
return $input.all().map((item, i) => {
  const servicio = $('Lista de servicios').itemMatching(i).json;
  const r = item.json;
  let codigo = null;
  let detalle;
  if (r.error) {
    const e = r.error;
    detalle = typeof e === 'string' ? e : (e.code || e.message || JSON.stringify(e));
  } else {
    codigo = r.statusCode ?? null;
    detalle = `código ${codigo}`;
  }
  return {
    json: {
      nombre: servicio.nombre,
      url: servicio.url,
      codigo,
      detalle,
      hayError: Boolean(r.error),
    },
  };
});

// Solo deja pasar los servicios que ANTES estaban arriba (o que nunca se habían revisado)
// Nota: el Static Data solo se guarda en ejecuciones de produccion (flujo activo)
const estado = $getWorkflowStaticData('global');
const salida = [];
for (const item of $input.all()) {
  const { nombre, url, detalle } = item.json;
  if (estado[url] !== 'caido') {
    salida.push({ json: { ...item.json, mensaje: `🔴 ${nombre} caído: ${url} (${detalle})` } });
  }
  estado[url] = 'caido';
}
return salida;

// Solo deja pasar los servicios que ANTES estaban caidos
const estado = $getWorkflowStaticData('global');
const salida = [];
for (const item of $input.all()) {
  const { nombre, url, detalle } = item.json;
  if (estado[url] === 'caido') {
    salida.push({ json: { ...item.json, mensaje: `🟢 ${nombre} recuperado: ${url} (${detalle})` } });
  }
  estado[url] = 'arriba';
}
return salida;
